head.script:
scwin.screenId = "jldfil05033";

///////// 1. 변수 및 선언 영역 /////////

scwin.form = null;


///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_bzCd", fn: function(){ return ((dma_readDataVO.get("bzCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.bzCd"); })()) === '0' || (dma_readDataVO.get("bzCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.bzCd"); })()) === '2'); } }, { id: "if_bzCd_2", fn: function(){ return ((dma_readDataVO.get("bzCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.bzCd"); })()) === '1' || (dma_readDataVO.get("bzCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.bzCd"); })()) === '3'); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_acntclsYymm", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "acntclsYymm")); } },
        { childId: "ipt_acntclsYymm_2", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(1, "acntclsYymm")); } },
        { childId: "ipt_acntclsYymm_3", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(2, "acntclsYymm")); } },
        { childId: "ipt_totAsstAmt", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "totAsstAmt")); } },
        { childId: "ipt_totAsstAmt_2", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(1, "totAsstAmt")); } },
        { childId: "ipt_totAsstAmt_3", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(2, "totAsstAmt")); } },
        { childId: "ipt_totDebtAmt", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "totDebtAmt")); } },
        { childId: "ipt_totDebtAmt_2", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(1, "totDebtAmt")); } },
        { childId: "ipt_totDebtAmt_3", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(2, "totDebtAmt")); } },
        { childId: "ipt_totCap", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "totCap")); } },
        { childId: "ipt_totCap_2", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(1, "totCap")); } },
        { childId: "ipt_totCap_3", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(2, "totCap")); } },
        { childId: "ipt_cap", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "cap")); } },
        { childId: "ipt_cap_2", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(1, "cap")); } },
        { childId: "ipt_cap_3", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(2, "cap")); } },
        { childId: "ipt_bzProftAmt", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "bzProftAmt")); } },
        { childId: "ipt_bzProftAmt_2", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(1, "bzProftAmt")); } },
        { childId: "ipt_bzProftAmt_3", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(2, "bzProftAmt")); } },
        { childId: "ipt_ordnincmAmt", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "ordnincmAmt")); } },
        { childId: "ipt_ordnincmAmt_2", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(1, "ordnincmAmt")); } },
        { childId: "ipt_ordnincmAmt_3", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(2, "ordnincmAmt")); } },
        { childId: "ipt_netincmAmt", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "netincmAmt")); } },
        { childId: "ipt_netincmAmt_2", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(1, "netincmAmt")); } },
        { childId: "ipt_netincmAmt_3", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(2, "netincmAmt")); } },
        { childId: "ipt_bzActivCashFlowAmt", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "bzActivCashFlowAmt")); } },
        { childId: "ipt_bzActivCashFlowAmt_2", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(1, "bzActivCashFlowAmt")); } },
        { childId: "ipt_bzActivCashFlowAmt_3", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(2, "bzActivCashFlowAmt")); } },
        { childId: "ipt_acntclsYymmTmp", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "acntclsYymm")); } },
        { childId: "ipt_acntclsYymmTmp_2", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(1, "acntclsYymm")); } },
        { childId: "ipt_acntclsYymmTmp_3", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(2, "acntclsYymm")); } },
        { childId: "ipt_fbzNetcap", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "fbzNetcap")); } },
        { childId: "ipt_fbzNetcap_2", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(1, "fbzNetcap")); } },
        { childId: "ipt_fbzNetcap_3", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(2, "fbzNetcap")); } },
        { childId: "ipt_totRiskAmt", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "totRiskAmt")); } },
        { childId: "ipt_totRiskAmt_2", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(1, "totRiskAmt")); } },
        { childId: "ipt_totRiskAmt_3", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(2, "totRiskAmt")); } },
        { childId: "ipt_reqPersisPrincCapVal", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "reqPersisPrincCapVal")); } },
        { childId: "ipt_reqPersisPrincCapVal_2", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(1, "reqPersisPrincCapVal")); } },
        { childId: "ipt_reqPersisPrincCapVal_3", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(2, "reqPersisPrincCapVal")); } },
        { childId: "ipt_eqtycap", fn: function () { return String(dlt_readDataVOArrayDrv.getCellData(0, "eqtycap")); } },
        { childId: "ipt_eqtycap_2", fn: function () { return String(dlt_readDataVOArrayDrv.getCellData(1, "eqtycap")); } },
        { childId: "ipt_otcDrvfncTrdTotRiskAmt", fn: function () { return String(dlt_readDataVOArrayDrv.getCellData(0, "otcDrvfncTrdTotRiskAmt")); } },
        { childId: "ipt_otcDrvfncTrdTotRiskAmt_2", fn: function () { return String(dlt_readDataVOArrayDrv.getCellData(1, "otcDrvfncTrdTotRiskAmt")); } },
        { childId: "ipt_fbzNetcap_4", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "fbzNetcap")); } },
        { childId: "ipt_eqtycap_3", fn: function () { return String(dlt_readDataVOArrayDrv.getCellData(0, "eqtycap")); } },
        { childId: "ipt_totRiskAmt_4", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "totRiskAmt")); } },
        { childId: "ipt_otcDrvfncTrdTotRiskAmt_3", fn: function () { return String(dlt_readDataVOArrayDrv.getCellData(0, "otcDrvfncTrdTotRiskAmt")); } },
        { childId: "ipt_reqPersisPrincCapVal_4", fn: function () { return String(dlt_readDataVOArrayFnc.getCellData(0, "reqPersisPrincCapVal")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.form = (document.ElwForm || { elements: [] });
        $c.util.getComponent('slc_audtOpinTpCd').setItemDisabled(0, !!(true));
        $c.util.getComponent('slc_audtOpinTpCd').setItemDisabled(1, !!(true));
        $c.util.getComponent('slc_audtOpinTpCd').setItemDisabled(2, !!(true));
        scwin.calNetRto(1);
        scwin.calNetRto(2);
        scwin.calNetRto(3);
        scwin.commaValueAll();
        scwin.commaValueAllN();
        scwin.calNetRto();
        scwin.calNetRto(1);
        scwin.calOtcRto();
        scwin.commaValueAll();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05033.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldfil05033: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil05033.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @method
