 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_ElwPageUsrSearch_onclick = async function(e){
    const ev = e;
    const event = ev;
    const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
    /* sdd-asis-lifecycle:begin btn_ElwPageUsrSearch_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    await scwin.elwPageUsrSearch()
    /* sdd-asis-lifecycle:end */
};

/**
 * @event
