 * @param e
 * @returns
 * @hidden N
*/
scwin.__ev_2_btn_ElwPageUsrSearch_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin __ev_2_btn_ElwPageUsrSearch_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.elwPageUsrSearch()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05033.__ev_2_btn_ElwPageUsrSearch_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.calOtcRto
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.calOtcRto = function () {
    /* sdd-asis-lifecycle:begin fn_CalOtcRto — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (($c.util.getComponent('ipt_otcDrvfncTrdTotRiskAmt').getValue() == null ? '' : String($c.util.getComponent('ipt_otcDrvfncTrdTotRiskAmt').getValue())) !== '' && ($c.util.getComponent('ipt_eqtycap').getValue() == null ? '' : String($c.util.getComponent('ipt_eqtycap').getValue())) !== '') {
        $c.util.getComponent('ipt_otcRto').setValue(Math.round((scwin.rmComma($c.util.getComponent('ipt_otcDrvfncTrdTotRiskAmt').getValue()) / scwin.rmComma($c.util.getComponent('ipt_eqtycap').getValue())) * 10000) / 100);
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.calNetRto
 * @author Inswave
 * @date 2026. 09. 29
 * @param num
 * @returns
 * @hidden N
*/
scwin.calNetRto = function (num) {
    /* sdd-asis-lifecycle:begin fn_CalNetRto — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (num == 1) {
        if (($c.util.getComponent('ipt_fbzNetcap').getValue() == null ? '' : String($c.util.getComponent('ipt_fbzNetcap').getValue())) !== '' && ($c.util.getComponent('ipt_totRiskAmt').getValue() == null ? '' : String($c.util.getComponent('ipt_totRiskAmt').getValue())) !== '' && ($c.util.getComponent('ipt_reqPersisPrincCapVal').getValue() == null ? '' : String($c.util.getComponent('ipt_reqPersisPrincCapVal').getValue())) !== '') {
            $c.util.getComponent('ipt_netRto').setValue(Math.round(((scwin.rmComma($c.util.getComponent('ipt_fbzNetcap').getValue()) - scwin.rmComma($c.util.getComponent('ipt_totRiskAmt').getValue())) / scwin.rmComma($c.util.getComponent('ipt_reqPersisPrincCapVal').getValue())) * 10000) / 100);
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.rmComma
 * @author Inswave
 * @date 2026. 09. 29
 * @param str
 * @returns
 * @hidden N
*/
scwin.rmComma = function (str) {
    /* sdd-asis-lifecycle:begin fn_RmComma — as-is 원문 본문(전환 이관 · 포팅 적용됨) */

    //	if( str == null || str == "" || str == 0 ) return '';
    //	if( str == null || str == ""  ) return '';
    if( str == null || str === ""  ) return Number(str);			//2009.07.02 수정. 항목 미입력시 합계 오류발생

    reg =  new RegExp(",","g");  

    return Number(str.replace(reg,''));
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.commaValueAll
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.commaValueAll = function () {
    /* sdd-asis-lifecycle:begin fn_CommaValueAll — as-is 원문 본문(전환 이관 · 포팅 적용됨) */

    for(let i=0 ; i < 3 ; i++ ) {
        fn_ObjValueSetComma($c.util.getComponent(["ipt_totAsstAmt", "ipt_totAsstAmt_2", "ipt_totAsstAmt_3"][i])); // 총자산금액                                        
        fn_ObjValueSetComma($c.util.getComponent(["ipt_cap", "ipt_cap_2", "ipt_cap_3"][i])); // 자본금                                          
        fn_ObjValueSetComma($c.util.getComponent(["ipt_totDebtAmt", "ipt_totDebtAmt_2", "ipt_totDebtAmt_3"][i])); // 총부채금액                                        
        fn_ObjValueSetComma($c.util.getComponent(["ipt_totCap", "ipt_totCap_2", "ipt_totCap_3"][i])); // 총자본금                                          
        fn_ObjValueSetComma($c.util.getComponent(["ipt_bzProftAmt", "ipt_bzProftAmt_2", "ipt_bzProftAmt_3"][i])); // 영업이익금액                                      
        fn_ObjValueSetComma($c.util.getComponent(["ipt_ordnincmAmt", "ipt_ordnincmAmt_2", "ipt_ordnincmAmt_3"][i])); // 경상이익금액                                      
        fn_ObjValueSetComma($c.util.getComponent(["ipt_netincmAmt", "ipt_netincmAmt_2", "ipt_netincmAmt_3"][i])); // 당기순이익금액                                    
        fn_ObjValueSetComma($c.util.getComponent(["ipt_bzActivCashFlowAmt", "ipt_bzActivCashFlowAmt_2", "ipt_bzActivCashFlowAmt_3"][i])); // 영업활동현금흐름금액                              
        fn_ObjValueSetComma($c.util.getComponent(["ipt_fbzNetcap", "ipt_fbzNetcap_2", "ipt_fbzNetcap_3", "ipt_fbzNetcap_4"][i])); // 영업용순자본금                                    
        fn_ObjValueSetComma($c.util.getComponent(["ipt_totRiskAmt", "ipt_totRiskAmt_2", "ipt_totRiskAmt_3", "ipt_totRiskAmt_4"][i])); // 총위험금액 
        fn_ObjValueSetComma($c.util.getComponent(["ipt_reqPersisPrincCapVal", "ipt_reqPersisPrincCapVal_2", "ipt_reqPersisPrincCapVal_3", "ipt_reqPersisPrincCapVal_4"][i])); // 필요유지자기자본
        fn_ObjValueSetComma($c.util.getComponent(["ipt_netRto", "ipt_netRto_2", "ipt_netRto_3", "ipt_netRto_4", "ipt_netRto_5"][i])); // 순자본비율

        fn_ObjValueSetComma($c.util.getComponent(["ipt_eqtycap", "ipt_eqtycap_2", "ipt_eqtycap_3"][i])); // 자기자본금                                        
        fn_ObjValueSetComma($c.util.getComponent(["ipt_otcDrvfncTrdTotRiskAmt", "ipt_otcDrvfncTrdTotRiskAmt_2", "ipt_otcDrvfncTrdTotRiskAmt_3"][i])); // 장외파생금융상품거래총위험금액                    
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.commaValueAllN
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.commaValueAllN = function () {
    /* sdd-asis-lifecycle:begin fn_CommaValueAll_N — as-is 원문 본문(전환 이관 · 포팅 적용됨) */

    for(let i=0 ; i < 3 ; i++ ) {
        fn_ObjValueSetComma($c.util.getComponent(["ipt_totAsstAmt", "ipt_totAsstAmt_2", "ipt_totAsstAmt_3"][i])); // 총자산금액                                        
        fn_ObjValueSetComma($c.util.getComponent(["ipt_cap", "ipt_cap_2", "ipt_cap_3"][i])); // 자본금                                          
        fn_ObjValueSetComma($c.util.getComponent(["ipt_totDebtAmt", "ipt_totDebtAmt_2", "ipt_totDebtAmt_3"][i])); // 총부채금액                                        
        fn_ObjValueSetComma($c.util.getComponent(["ipt_totCap", "ipt_totCap_2", "ipt_totCap_3"][i])); // 총자본금                                          
        fn_ObjValueSetComma($c.util.getComponent(["ipt_bzProftAmt", "ipt_bzProftAmt_2", "ipt_bzProftAmt_3"][i])); // 영업이익금액                                      
        fn_ObjValueSetComma($c.util.getComponent(["ipt_ordnincmAmt", "ipt_ordnincmAmt_2", "ipt_ordnincmAmt_3"][i])); // 경상이익금액                                      
        fn_ObjValueSetComma($c.util.getComponent(["ipt_netincmAmt", "ipt_netincmAmt_2", "ipt_netincmAmt_3"][i])); // 당기순이익금액                                    
        fn_ObjValueSetComma($c.util.getComponent(["ipt_bzActivCashFlowAmt", "ipt_bzActivCashFlowAmt_2", "ipt_bzActivCashFlowAmt_3"][i])); // 영업활동현금흐름금액                              
        fn_ObjValueSetComma($c.util.getComponent(["ipt_fbzNetcap", "ipt_fbzNetcap_2", "ipt_fbzNetcap_3", "ipt_fbzNetcap_4"][i])); // 영업용순자본금                                    
        fn_ObjValueSetComma($c.util.getComponent(["ipt_totRiskAmt", "ipt_totRiskAmt_2", "ipt_totRiskAmt_3", "ipt_totRiskAmt_4"][i])); // 총위험금액 

        fn_ObjValueSetComma($c.util.getComponent(["ipt_eqtycap", "ipt_eqtycap_2", "ipt_eqtycap_3"][i])); // 자기자본금                                        
        fn_ObjValueSetComma($c.util.getComponent(["ipt_otcDrvfncTrdTotRiskAmt", "ipt_otcDrvfncTrdTotRiskAmt_2", "ipt_otcDrvfncTrdTotRiskAmt_3"][i])); // 장외파생금융상품거래총위험금액                    
    }
    /* sdd-asis-lifecycle:end */
};


